    // MARK: - Privacy (TR)

    private static let privacyTurkish: [LegalSection] = [
        LegalSection(id: "1", title: "1. Giriş", body: "Bu Gizlilik Politikası, Sophia'nın (bundan böyle “biz”, “bizim” veya “Uygulama”) kişisel bilgilerinizi nasıl topladığını, kullandığını ve koruduğunu açıklar. Gizliliğinizi korumayı ve verilerinizi şeffaf bir şekilde işlemeyi taahhüt ediyoruz."),
        LegalSection(id: "2", title: "2. Toplanan veriler", body: "Sophia, veri minimizasyonu ilkesine göre tasarlanmıştır. Uygulama cihazınızda şunları saklar:\n\n- Kurslardaki ve quizlerdeki ilerlemeniz\n- Tercihleriniz (ilgi alanlarınız, hedefleriniz)\n- Seriniz (art arda kullanım günleri)\n- Favori kurslarınız\n\nBu yerel veriler sunucularımıza aktarılmaz.\n\nAyarlar'daki form aracılığıyla bize geri bildirim gönderirseniz, size yanıt verebilmemiz için mesajınız ve girdiyseniz e-posta adresiniz Formspree'ye iletilir. Teknik bilgiler (uygulama sürümü, dil, cihaz) otomatik olarak eklenir."),
        LegalSection(id: "3", title: "3. Abonelik verileri", body: "Premium plana abone olursanız işlem tamamen Apple tarafından App Store aracılığıyla gerçekleştirilir. Ödeme bilgilerinize (kart numarası, fatura adresi) erişimimiz yok. Abonelik durumunuzun onayını yalnızca abonelik yönetimi ortağımız RevenueCat aracılığıyla alırız."),
