    private static let termsPolish: [LegalSection] = [
        LegalSection(id: "1", title: "1. Akceptacja regulaminu", body: "Pobierając aplikację Sophia (dalej „Aplikacja”), instalując ją lub z niej korzystając, akceptujesz niniejszy Regulamin korzystania z Aplikacji („Regulamin”) i zobowiązujesz się go przestrzegać. Jeśli nie akceptujesz Regulaminu, nie korzystaj z Aplikacji."),
