    // MARK: - Terms (SK)

    private static let termsSlovak: [LegalSection] = [
        LegalSection(id: "1", title: "1. Prijatie podmienok", body: "Stiahnutím, inštaláciou alebo používaním aplikácie Sophia (ďalej len „aplikácia“) súhlasíš s tým, že ťa viažu tieto Všeobecné podmienky používania (ďalej len „podmienky“). Ak s týmito podmienkami nesúhlasíš, aplikáciu nepoužívaj."),
        LegalSection(id: "2", title: "2. Popis služby", body: "Sophia je vzdelávacia mobilná aplikácia zameraná na všeobecný rozhľad, ktorá ponúka kurzy, kvízy a interaktívny obsah. Aplikácia je dostupná pre iOS a môže ponúkať obsah zadarmo aj predplatné Premium."),
        LegalSection(id: "3", title: "3. Účet a používanie", body: "Ponúkame možnosť vytvoriť si účet (cez Apple alebo Google), vďaka ktorému sa tvoj pokrok uloží a synchronizuje medzi tvojimi zariadeniami. Noví používatelia sa prihlasujú pri úvodnom nastavení aplikácie; existujúci používatelia si môžu účet vytvoriť kedykoľvek v nastaveniach. Bez účtu sa údaje o tvojom pokroku ukladajú lokálne v tvojom zariadení a pri preinštalovaní aplikácie sa môžu stratiť. Svoj účet môžeš kedykoľvek zmazať v nastaveniach."),
        LegalSection(id: "4", title: "4. Predplatné a nákupy", body: "Sophia ponúka predplatné Premium (mesačné a ročné) cez App Store od spoločnosti Apple. Ceny sú uvedené v aplikácii a môžu sa líšiť podľa krajiny. Platba sa strhne z tvojho účtu Apple ID pri potvrdení nákupu. Predplatné sa automaticky obnovuje, ak automatické obnovenie nevypneš aspoň 24 hodín pred koncom aktuálneho obdobia. Predplatné môžeš spravovať a zrušiť v nastaveniach svojho účtu App Store."),
        LegalSection(id: "5", title: "5. Skúšobné obdobie zadarmo", body: "Novým používateľom môže byť ponúknuté skúšobné obdobie zadarmo. Po jeho skončení sa predplatné automaticky zmení na platené, ak ho vopred nezrušíš. Ak si počas skúšobného obdobia zadarmo kúpiš predplatné, nevyužitá časť skúšobného obdobia prepadne."),
        LegalSection(id: "6", title: "6. Duševné vlastníctvo", body: "Všetok obsah aplikácie (texty, ilustrácie, dizajn, logo, kurzy, kvízy) je chránený autorským právom a zostáva výhradným vlastníctvom Sophie. Akékoľvek neoprávnené rozmnožovanie, šírenie alebo používanie je prísne zakázané."),
        LegalSection(id: "7", title: "7. Obmedzenie zodpovednosti", body: "Obsah v aplikácii slúži na vzdelávacie a informačné účely. Sophia nezaručuje presnosť, úplnosť ani aktuálnosť uvedených informácií. Aplikácia sa poskytuje „tak, ako je“, bez akejkoľvek záruky."),
        LegalSection(id: "8", title: "8. Zmeny podmienok", body: "Sophia si vyhradzuje právo tieto podmienky kedykoľvek zmeniť. O podstatných zmenách budú používatelia informovaní. Ak budeš aplikáciu po zmene naďalej používať, znamená to, že s novými podmienkami súhlasíš."),
        LegalSection(id: "9", title: "9. Rozhodné právo", body: "Tieto podmienky sa riadia francúzskym právom. Všetky spory týkajúce sa ich výkladu alebo plnenia budú riešiť príslušné súdy."),
        LegalSection(id: "10", title: "10. Kontakt", body: "S akýmikoľvek otázkami k týmto podmienkam nás môžeš kontaktovať cez App Store alebo e-mailom na adrese uvedenej na našej stránke v App Store."),
    ]

    // MARK: - Privacy (SK)

    private static let privacySlovak: [LegalSection] = [
        LegalSection(id: "1", title: "1. Úvod", body: "Tieto zásady ochrany súkromia opisujú, ako Sophia (ďalej len „my“, „náš“ alebo „aplikácia“) zhromažďuje, používa a chráni tvoje osobné údaje. Zaväzujeme sa chrániť tvoje súkromie a s tvojimi údajmi zaobchádzať transparentne."),
        LegalSection(id: "2", title: "2. Zozbierané údaje", body: "Sophia je navrhnutá podľa zásady minimalizácie údajov. Aplikácia ukladá v tvojom zariadení:\n\n- Tvoj pokrok v kurzoch a kvízoch\n- Tvoje preferencie (záujmy, ciele)\n- Tvoju sériu (počet dní používania v rade)\n- Tvoje obľúbené kurzy\n\nTieto lokálne údaje sa na naše servery neodosielajú.\n\nAk nám pošleš spätnú väzbu cez formulár v nastaveniach, tvoja správa a e-mailová adresa (ak ju vyplníš) sa odošlú službe Formspree, aby sme ti mohli odpovedať. Automaticky sa k nim pripoja technické informácie (verzia aplikácie, jazyk, zariadenie)."),
        LegalSection(id: "3", title: "3. Údaje o predplatnom", body: "Ak si kúpiš predplatné Premium, transakciu spracúva výhradne Apple cez App Store. Nemáme prístup k tvojim platobným údajom (číslo karty, fakturačná adresa). Dostávame iba potvrdenie o stave tvojho predplatného, a to cez RevenueCat, nášho partnera na správu predplatného."),
        LegalSection(id: "4", title: "4. RevenueCat", body: "Na správu predplatného v aplikácii používame RevenueCat. RevenueCat môže zhromažďovať anonymný identifikátor zariadenia, aby overil stav tvojho predplatného. Nezdieľajú sa žiadne údaje, podľa ktorých by sa dala zistiť tvoja totožnosť. Viac informácií nájdeš v zásadách ochrany súkromia na webovej stránke RevenueCat."),
        LegalSection(id: "5", title: "5. Apple Analytics", body: "Aplikácia môže využívať aj anonymné štatistiky, ktoré poskytuje Apple (App Analytics). Tieto údaje sú súhrnné a nedá sa podľa nich zistiť tvoja totožnosť. Zdieľanie analytických údajov môžeš vypnúť v nastaveniach iPhonu (Nastavenia > Súkromie > Analytika a vylepšenia)."),
        LegalSection(id: "6", title: "6. Ukladanie dát", body: "Údaje o tvojom pokroku sa ukladajú lokálne v tvojom zariadení (UserDefaults). Ak si vytvoríš účet (Apple alebo Google), bezpečne sa zálohujú aj na naše servery Supabase (umiestnené v Európskej únii), aby sa dali synchronizovať medzi tvojimi zariadeniami. Odinštalovaním aplikácie sa lokálne údaje vymažú; zmazaním účtu sa natrvalo vymažú aj súvisiace údaje na serveri."),
        LegalSection(id: "7", title: "7. Zdieľanie údajov", body: "Osobné údaje nepredávame, neprenajímame ani nezdieľame s tretími stranami na komerčné ani reklamné účely. Údaje odovzdávame iba týmto subjektom: Apple a RevenueCat (predplatné), Formspree (spätná väzba, ktorú používatelia dobrovoľne pošlú z nastavení)."),
        LegalSection(id: "8", title: "8. Práva používateľov", body: "V súlade so všeobecným nariadením o ochrane údajov (GDPR) a platnými právnymi predpismi máš tieto práva:\n\n- Právo na prístup k svojim údajom\n- Právo na opravu\n- Právo na vymazanie (vynulovanie v nastaveniach)\n- Právo na prenosnosť údajov\n- Právo namietať\n\nAk chceš tieto práva uplatniť, kontaktuj nás na adrese uvedenej na našej stránke v App Store."),
        LegalSection(id: "9", title: "9. Ochrana maloletých", body: "Sophia je vzdelávacia aplikácia vhodná pre všetky vekové kategórie. Vedome nezhromažďujeme osobné údaje od detí mladších ako 16 rokov. Aplikácia neobsahuje žiadny nevhodný obsah."),
        LegalSection(id: "10", title: "10. Zmeny", body: "Vyhradzujeme si právo tieto zásady kedykoľvek upraviť. Akékoľvek zmeny budú oznámené prostredníctvom aktualizácie aplikácie.\n\nPosledná aktualizácia: september 2026"),
    ]
